<script lang="ts">
  import { page } from '$app/stores'; import { onMount } from 'svelte'; import type { RunSummary } from '@sty/contracts';
  import CircleAlert from 'lucide-svelte/icons/circle-alert'; import CircleCheck from 'lucide-svelte/icons/circle-check'; import CircleDot from 'lucide-svelte/icons/circle-dot'; import GitBranch from 'lucide-svelte/icons/git-branch';
  import FilterBar from '$lib/components/FilterBar.svelte'; import { api } from '$lib/api';
  const owner=$derived($page.params.owner);const repo=$derived($page.params.repo);let runs=$state<RunSummary[]>([]);let loading=$state(true);let error=$state(false);
  onMount(async()=>{try{runs=(await api<{runs:RunSummary[]}>(`/repositories/${owner}/${repo}/runs`)).runs}catch{error=true}finally{loading=false}});
</script>
<svelte:head><title>Runs · {owner}/{repo} · Sty</title></svelte:head>
<header class="heading"><div><h1>Runs</h1><p>Workflow activity on every branch in this repository.</p></div><a href="/{owner}/{repo}/runs/new">New run</a></header><FilterBar placeholder="Search workflow runs" tabs={['All']} active="All" />{#if error}<p class="notice" role="alert">Runs could not be loaded. Refresh to try again.</p>{/if}<section class="list">{#each runs as run}<a class="row" href="/{owner}/{repo}/runs/{run.number}"><span class="state {run.state}">{#if run.state==='running'||run.state==='queued'}<CircleDot size={16}/>{:else if run.state==='failure'}<CircleAlert size={16}/>{:else}<CircleCheck size={16}/>{/if}</span><span class="main"><strong>{run.name}</strong><small>Run #{run.number} · {run.queuedAt}</small><code><GitBranch size={10}/>{run.branch}<i>{run.commit.slice(0,7)}</i></code></span><span class="jobs">{run.jobs} {run.jobs===1?'job':'jobs'}</span><span class="status">{run.state}</span></a>{:else}{#if !loading}<div class="empty"><strong>No runs yet</strong><p>Workflow activity from this repository will appear here.</p></div>{/if}{/each}</section>
<style>
  .heading{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:23px}.heading>a{display:inline-flex;height:30px;align-items:center;padding:0 9px;border-radius:5px;background:var(--brand);color:#fff;font-size:9px;font-weight:650;text-decoration:none}h1{margin:0;color:var(--text-strong);font-size:22px;letter-spacing:-.03em}p{margin:6px 0 0;color:var(--text-muted);font-size:11px}.list{border-top:1px solid var(--border)}.row{display:grid;grid-template-columns:29px minmax(0,1fr) 55px 55px;align-items:center;gap:10px;min-height:68px;padding:9px 4px;border-bottom:1px solid var(--border-subtle);color:inherit;text-decoration:none}.row:hover{background:var(--surface-hover)}.state{display:grid;width:27px;height:27px;place-items:center;color:var(--text-faint)}.state.running,.state.queued{color:var(--brand)}.state.failure{color:var(--danger)}.state.success{color:var(--success)}.main strong,.main small{display:block}.main strong{color:var(--text-strong);font-size:11px}.main small{margin-top:3px;color:var(--text-muted);font-size:9px}code{display:flex;align-items:center;gap:4px;margin-top:4px;color:var(--text-muted);font-size:9px}code i{color:var(--text-faint);font-style:normal}.jobs,.status{color:var(--text-faint);font-size:9px}.status{text-transform:capitalize}.notice{color:var(--warning);font-size:10px}.empty{padding:48px 4px;text-align:center}.empty strong{color:var(--text-strong);font-size:12px}.empty p{color:var(--text-faint);font-size:10px}@media(max-width:600px){.row{grid-template-columns:29px minmax(0,1fr) 50px}.jobs{display:none}}
</style>
